1	/**
2	 * A simple Main class which is used to quickly initialise the 
3	 * simulation.
4	 *
5	 * @version 26/02/2022
6	 */
7	public class Main
8	{
9	    public static void main(String[] args) {
10	        Simulator simulator = new Simulator();
11	    }
