1	import java.util.Random;
2	import java.util.List;
3	import java.util.ArrayList;
4	//import java.util.Arrays;
5	import java.util.Iterator;
6	import java.awt.Color;
7	import javax.swing.JButton;
8	//import java.awt.event.ActionListener;
9	//import java.awt.event.ActionEvent;
10	//import javax.swing.SwingUtilities;
11	//import javafx.scene.paint.Color;
12	
13	/**
14	 * A simple predator-prey simulator, based on a rectangular field
15	 * containing rabbits and foxes.
16	 *
17	 * @version 26/02/2022
18	 */
19	public class Simulator
20	{
21	    // Constants representing configuration information for the simulation.
22	    // The default width for the grid.
23	    private static final int DEFAULT_WIDTH = 270;
24	    // The default depth of the grid.
25	    private static final int DEFAULT_DEPTH = 180;
26	    // The probability that a lion will be created in any given grid position.
27	    private static final double LION_CREATION_PROBABILITY = 0.0125; //0.015
28	    // The probability that a cheetah will be created in any given grid position.
29	    private static final double CHEETAH_CREATION_PROBABILITY = 0.0125; //0.015
30	    // The probability that a zebra will be created in any given grid position.
31	    private static final double ZEBRA_CREATION_PROBABILITY = 0.08; //0.08
32	    // The probability that a giraffe will be created in any given grid position.
33	    private static final double GIRAFFE_CREATION_PROBABILITY = 0.08; //0.08
34	    // The probability that a giraffe will be created in any given grid position.
35	    private static final double LEMUR_CREATION_PROBABILITY = 0.081; //0.08
36	
37	    // List of animals in the field.
38	    private List<LivingOrganism> animals;
39	    // List of plants in the field
40	    private List<LivingOrganism> plants;
41	    // The current state of the field.
42	    private Field field;
43	    // A graphical view of the simulation.
44	    private SimulatorView view;
45	    // List of buttons that are used to control the simulation.
46	    private JButton[] buttons;
47	    
48	    /**
49	     * Construct a simulation field with default size.
50	     */
51	    public Simulator()
52	    {
53	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
54	    }
55	    
56	    /**
57	     * Create a simulation field with the given size.
58	     * @param depth Depth of the field. Must be greater than zero.
59	     * @param width Width of the field. Must be greater than zero.
60	     */
61	    public Simulator(int depth, int width)
62	    {
63	        if(width <= 0 || depth <= 0) {
64	            System.out.println("The dimensions must be greater than zero.");
65	            System.out.println("Using default values.");
66	            depth = DEFAULT_DEPTH;
67	            width = DEFAULT_WIDTH;
68	        }
69	        
70	        animals = new ArrayList<>();
71	        plants = new ArrayList<>();
72	        field = new Field(depth, width);
73	        buttons = new JButton[5];
74	        
75	        // Creates the buttons for the view
76	        JButton playPause = new JButton("Play");
77	            playPause.addActionListener(e -> new Thread(() -> playPauseButton()).start());
78	            buttons[0] = playPause;
79	            
80	        JButton runLongSim = new JButton("Run Long Sim");
81	            runLongSim.addActionListener(e -> new Thread(() -> runLongSimulation()).start());
82	            buttons[1] = runLongSim;
83	        
84	        JButton simOneStep = new JButton("Sim One Step");
85	            simOneStep.addActionListener(e -> simulateOneStep());
86	            buttons[2] = simOneStep;
87	            
88	        JButton reset = new JButton("Reset");
89	            reset.addActionListener(e -> reset());
90	            buttons[3] = reset;
91	            
92	        JButton quit = new JButton("Quit");
93	            quit.addActionListener(e -> quit());
94	            buttons[4] = quit;
95	        
96	        // Sets the visibility of the buttons in accordance to the current state of the simulation.
97	        buttonToggle();
98	
99	        // Create a view of the state of each location in the field.
100	        view = new SimulatorView(depth, width, buttons);
101	        view.setColor(Zebra.class, Color.BLACK, Color.WHITE);
102	        view.setColor(Giraffe.class, Color.YELLOW, Color.BLACK);
103	        view.setColor(Lemur.class, Color.BLUE, Color.WHITE);
104	        view.setColor(Lion.class, Color.RED, Color.WHITE);
105	        view.setColor(Cheetah.class, Color.ORANGE, Color.BLACK);
106	        view.setColor(Plant.class, Color.GREEN, Color.BLACK);
107	        
108	        // Setup a valid starting point.
109	        reset();
110	    }
111	    
112	    /**
113	     * Controls the functionality of the Play/Pause button. This depends
114	     * on whether the simulation is paused or not.
115	     */
116	    private void playPauseButton() 
117	    {
118	        boolean isPaused = Time.getIsPaused();
119	        
120	        Time.toggleIsPaused();
121	        
122	        if (isPaused) {
123	            if (! Time.getIsFinished()) {
124	                simulate();
125	            }
126	        }
127	        
128	        buttonToggle();
129	    }
130	    
131	    /**
132	     * Run the simulation from its current state for a reasonably long 
133	     * period: 500 steps.
134	     */
135	    private void runLongSimulation()
136	    {
137	        simulate(500);
138	    }
139	    
140	    /**
141	     * Run the simulation from its current state for the given number of 
142	     * steps.
143	     * @param numSteps The number of steps to run for.
144	     */
145	    private void simulate(int numSteps)
146	    {
147	        // Sets the number of steps that the simulation run started at
148	        Time.setStepsToRunFor(numSteps);
149	        simulate();
150	    }
151	    
152	    /**
153	     * Run the simulation from its current state for the given number of 
154	     * steps in the Time Class.
155	     * Stop before the given number of steps if it ceases to be viable.
156	     * This is considered to be when only one species remains.
157	     */
158	    private void simulate() 
159	    {
160	        Time.setIsPaused(false);
161	        
162	        // Adjust button visibility.
163	        buttonToggle();
164	        
165	        while (! Time.getIsPaused() && ! Time.getIsFinished() && view.isViable(field)) {
166	            simulateOneStep();
167	        }
168	        
169	        Time.setIsPaused(true);
170	        buttonToggle();
171	    }
172	    
173	    /**
174	     * Run the simulation from its current state for a single step.
175	     * Iterate over the whole field updating the state of each
176	     * predator, prey, and plant.
177	     */
178	    private void simulateOneStep()
179	    {
180	        Time.incrementStep();
181	        Weather.updateWeather();
182	
183	        // Provide space for newborn animals and plants;
184	        List<LivingOrganism> newAnimals = new ArrayList<>();
185	        List<LivingOrganism> newPlants = new ArrayList<>();
186	        
187	        // Let all animals act.
188	        for(Iterator<LivingOrganism> it = animals.iterator(); it.hasNext(); ) 
189	        {
190	            Animal animal = (Animal) it.next();
191	            
192	            if(animal != null) 
193	            {
194	                animal.act(newAnimals);
195	                
196	                if (! animal.isAlive())
197	                {
198	                    it.remove();
199	                }
200	            }
201	        }
202	        
203	        // Let all plants act.
204	        for(Iterator<LivingOrganism> it = plants.iterator(); it.hasNext(); ) {
205	            Plant plant = (Plant) it.next();
206	            if(plant != null) 
207	            {
208	                plant.act(newPlants);
209	                
210	                if (! plant.isAlive())
211	                {
212	                    it.remove();
213	                }
214	            }
215	        }
216	        
217	        // Add the newly born animals and plants to the main lists.
218	        animals.addAll(newAnimals);
219	        plants.addAll(newPlants); 
220	
221	        // Show the current state in the view.
222	        view.showStatus(field);
223	    }
224	        
225	    /**
226	     * Reset the simulation to a starting position.
227	     */
228	    private void reset()
229	    {
230	        // Resets the visibility of the buttons and resets the step number
231	        Time.resetStep();
232	        buttonToggle();
233	        
234	        // Clears all current animals and plants then repopulates the area
235	        animals.clear();
236	        plants.clear();
237	        populate();
238	        
239	        // Show the starting state in the view.
240	        view.showStatus(field);
241	    }
242	    
243	    /**
244	     * Randomly populate the field with predators, prey, and plants.
245	     */
246	    private void populate()
247	    {
248	        Random rand = Randomizer.getRandom();
249	        field.clear();
250	        for(int row = 0; row < field.getDepth(); row++) 
251	        {
252	            for(int col = 0; col < field.getWidth(); col++) 
253	            {
254	                //plants will fill the entire field initially.
255	                Location location = new Location(row, col);
256	                Plant plant = new Plant(true, field, location);
257	                plants.add(plant);
258	                
259	                Animal animal = null;
260	                
261	                if(rand.nextDouble() <= LION_CREATION_PROBABILITY) 
262	                {
263	                     animal = (Lion) new Lion(true, field, location, false, false);
264	                }
265	                else if(rand.nextDouble() <= CHEETAH_CREATION_PROBABILITY)
266	                {
267	                     animal = (Cheetah) new Cheetah(true, field, location, false, false);
268	                }
269	                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) 
270	                {
271	                     animal = (Zebra) new Zebra(true, field, location, false, false);
272	                }
273	                else if(rand.nextDouble() <= GIRAFFE_CREATION_PROBABILITY)
274	                {
275	                     animal = (Giraffe) new Giraffe(true, field, location, false, false);
276	                }
277	                else if(rand.nextDouble() <= LEMUR_CREATION_PROBABILITY) 
278	                {
279	                     animal = (Lemur) new Lemur(true, field, location, false, false);
280	                }
281	                
282	                if(animal != null) 
283	                {
284	                    animals.add(animal);
285	                }
286	            }
287	        }
288	    }
289	    
290	    /**
291	     * Pause for a given time.
292	     * @param millisec  The time to pause for, in milliseconds
293	     */
294	    private void delay(int millisec)
295	    {
296	        try {
297	            Thread.sleep(millisec);
298	        }
299	        catch (InterruptedException ie) {
300	            // wake up
301	        }
302	    }
303	    
304	    /**
305	     * Sets the visibility of the buttons in accordance with the current
306	     * state of the simulation.
307	     */
308	    private void buttonToggle() 
309	    {
310	        boolean isPaused = Time.getIsPaused();
311	        boolean isFinished = Time.getIsFinished();
312	        
313	        boolean isStopped = false;
314	        if (isPaused || isFinished) 
315	        {
316	            isStopped = true;
317	        }
318	        
319	        // Adjust button usability.
320	        buttons[0].setEnabled(!isFinished);
321	        buttons[1].setEnabled(isStopped);
322	        buttons[2].setEnabled(isStopped);
323	        buttons[3].setEnabled(isStopped);
324	        
325	        // Set the label on the play/pause button.
326	        if (isStopped) 
327	        {
328	            buttons[0].setLabel("Play");   
329	        }
330	        else {
331	            buttons[0].setLabel("Pause");
332	        }
333	    }
334	    
335	    /**
336	     * Used by the quit button to close the application.
337	     */
338	    private void quit()
339	    {
340	        System.exit(0);
341	    }
342	}
