1	import java.awt.*;
2	import java.awt.event.*;
3	import javax.swing.*;
4	import java.util.LinkedHashMap;
5	import java.util.Map;
6	
7	/**
8	 * A graphical view of the simulation grid.
9	 * The view displays a colored rectangle for each location 
10	 * representing its contents. It uses a default background color.
11	 * Colors for each type of species can be defined using the
12	 * setColor method.
13	 *
14	 * @version 26/02/2022
15	 */
16	public class SimulatorView extends JFrame
17	{
18	    // Colors used for empty locations.
19	    private static final Color EMPTY_COLOR = Color.white;
20	
21	    // Color used for objects that have no defined color.
22	    private static final Color UNKNOWN_COLOR = Color.gray;
23	
24	    private final String STEP_PREFIX = "  Step: ";
25	    private final String POPULATION_PREFIX = "Population: ";
26	    private final String TIME_PREFIX = "Time: ";
27	    private final String WEATHER_PREFIX = "Weather: ";
28	    private final String INFECTED_PREFIX = "Infected: ";
29	    private final String IMMUNE_PREFIX = "Immune: ";
30	    
31	    private JLabel stepLabel, population, infoLabel, timeLabel, 
32	                   weatherLabel, infectedLabel, immuneLabel;
33	    
34	    // The view of the simulation.
35	    private FieldView fieldView;
36	    
37	    // Stores a graph key which displays the colors of the classes.
38	    private JPanel classKey;
39	    
40	    // A map for storing colors for participants in the simulation
41	    private Map<Class, Color> colors;
42	    
43	    // A statistics object computing and storing simulation information
44	    private FieldStats stats;
45	
46	    /**
47	     * Create a view of the given width and height.
48	     * @param height The simulation's height.
49	     * @param width The simulation's width.
50	     * @param buttons The buttons used to control the simulation.
51	     */
52	    public SimulatorView(int height, int width, JButton[] buttons)
53	    {
54	        stats = new FieldStats();
55	        colors = new LinkedHashMap<>();
56	
57	        setTitle("Savannah Simulation");
58	        stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
59	        population = new JLabel(POPULATION_PREFIX, JLabel.CENTER);
60	        timeLabel = new JLabel(TIME_PREFIX, JLabel.CENTER);
61	        weatherLabel = new JLabel(WEATHER_PREFIX, JLabel.CENTER);
62	        infectedLabel = new JLabel(INFECTED_PREFIX, JLabel.CENTER);
63	        immuneLabel = new JLabel(IMMUNE_PREFIX, JLabel.CENTER);
64	        
65	        fieldView = new FieldView(height, width);
66	
67	        // Initialise all the JFrame elements        
68	        Container contents = getContentPane();
69	        
70	        // The menu bar at the top of the screen
71	        JMenuBar optionsBar = makeMenuBar();
72	            setJMenuBar(optionsBar);
73	        
74	        // The labels above the simulator
75	        JPanel infoPanel = new JPanel(new GridLayout());
76	            infoPanel.add(stepLabel);
77	            infoPanel.add(timeLabel);
78	            infoPanel.add(weatherLabel);
79	        
80	        classKey = new JPanel(new GridLayout());
81	        
82	        // The labels below the simulator
83	        JPanel populationPanel = new JPanel(new BorderLayout());
84	            populationPanel.add(classKey, BorderLayout.NORTH);
85	            populationPanel.add(infectedLabel, BorderLayout.WEST);
86	            populationPanel.add(population, BorderLayout.CENTER);
87	            populationPanel.add(immuneLabel, BorderLayout.EAST);
88	            
89	        // Adds the buttons to the side menu panel.
90	        JPanel menuPanel = new JPanel();
91	            menuPanel.setLayout(new BoxLayout(menuPanel, BoxLayout.Y_AXIS));
92	            for (int i = 0; i < buttons.length; i++) {
93	                buttons[i].setAlignmentX(Component.CENTER_ALIGNMENT);
94	                menuPanel.add(buttons[i]);
95	            }
96	        
97	        // add everything to the windows
98	        contents.add(infoPanel, BorderLayout.NORTH);
99	        contents.add(menuPanel, BorderLayout.WEST);
100	        contents.add(fieldView, BorderLayout.CENTER);
101	        contents.add(populationPanel, BorderLayout.SOUTH);
102	        
103	        pack();
104	        setVisible(true);
105	    }
106	    
107	    /**
108	     * Creates a menu bar at the top of the screen which different 
109	     * options.
110	     * @return Returns the new menu bar.
111	     */
112	    public JMenuBar makeMenuBar() {
113	        JMenuBar menuBar = new JMenuBar();
114	        
115	        JMenu menu;
116	        JMenuItem menuItem;
117	        
118	        menu = new JMenu("Help");
119	            menuBar.add(menu);
120	        
121	            menuItem = new JMenuItem("Instructions");
122	                menuItem.addActionListener(e -> showInstructions());
123	                menu.add(menuItem);
124	                
125	            menuItem = new JMenuItem("About");
126	                menuItem.addActionListener(e -> showAbout());
127	                menu.add(menuItem);
128	        
129	        return menuBar;
130	    }
131	    
132	    /**
133	     * Displays a new popup screen containing instructions on how
134	     * to use the simulation.
135	     */
136	    public void showInstructions() 
137	    {
138	        String dialogue = "How to use:\n" +
139	                          "   - Use 'Play/Pause' button to stop and resume the simulation whilst in progress.\n" +
140	                          "   - Use the 'Run Long Sim' button to show the 500 steps of the simulation.\n" +
141	                          "   - Use the 'Sim One Step' button to show the next step of the simulation.\n" +
142	                          "   - Use the 'Reset' button whilst paused/finished to generate a brand new random seed.\n" +
143	                          "   - Use the 'Quit' button to exit the application.";
144	        JOptionPane.showMessageDialog (this, dialogue, "Instructions", JOptionPane.INFORMATION_MESSAGE);
145	    }
146	    
147	    /**
148	     * Displays a new popup screen containing information about the
149	     * project.
150	     */
151	    private void showAbout()
152	    {
153	        String dialogue = "Project: Savannah Simulation which is predator-prey-simulation\n" +
154	                          "Authors: \n" +
155	                          "             based on foxes-and-rabbits by Michael KÃ¶lling and David J. Barnes.\n\n" + 
156	                          "This project is based on part of the material for chapter 10 of the book\n" + 
157	                          "         Objects First with Java - A Practical Introduction using BlueJ\n" +
158	                          "         Sixth edition\n" +
159	                          "         David J. Barnes and Michael KÃ¶lling\n" +
160	                          "         Pearson Education, 2016\n\n" +
161	                          "A predator-prey simulation involving 2 predators (Cheetahs and Lions),\n" + 
162	                          "3 prey (Lemurs, Giraffes, and Zebras), and grass in an enclosed rectangular\n" + 
163	                          "field.";
164	        JOptionPane.showMessageDialog (this, dialogue, "About", JOptionPane.INFORMATION_MESSAGE);
165	    }
166	    
167	    /**
168	     * Define a color to be used for the given class.
169	     *
170	     * @param newClass The new Class' object.
171	     * @param classColor The color to be used for the given class.
172	     * @param textColor The color to be used for the text in the class key.
173	     */
174	    public void setColor(Class newClass, Color classColor, Color textColor)
175	    {
176	        colors.put(newClass, classColor);
177	        
178	        // Creates label of the appropriate color and text to be
179	        // displayed by the class key.
180	        JLabel newClassLabel = new JLabel(newClass.getName(), JLabel.CENTER);
181	        
182	        // Adjusts color of the label's text
183	        newClassLabel.setForeground(textColor);
184	        
185	        newClassLabel.setBackground(classColor);
186	        newClassLabel.setOpaque(true);
187	        
188	        classKey.add(newClassLabel);
189	    }
190	
191	    /**
192	     * @param animalClass The class to get the colour of.
193	     * 
194	     * @return The color to be used for a given class of animal.
195	     */
196	    private Color getColor(Class animalClass)
197	    {
198	        Color col = colors.get(animalClass);
199	        if(col == null) {
200	            // no color defined for this class
201	            return UNKNOWN_COLOR;
202	        }
203	        else {
204	            return col;
205	        }
206	    }
207	
208	    /**
209	     * Show the current status of the field.
210	     * 
211	     * @param field The field whose status is to be displayed.
212	     */
213	    public void showStatus(Field field)
214	    {
215	        if(!isVisible()) {
216	            setVisible(true);
217	        }
218	            
219	        stepLabel.setText(STEP_PREFIX + Time.getStep());
220	        timeLabel.setText(TIME_PREFIX + getTimeString());
221	        weatherLabel.setText(WEATHER_PREFIX + Weather.getWeather() + "  ");
222	        stats.reset();
223	        
224	        fieldView.preparePaint();
225	        
226	        // Used to tally up the respective counts.
227	        int numberOfInfected = 0;
228	        int numberOfImmune = 0;
229	        
230	        for(int row = 0; row < field.getDepth(); row++) 
231	        {
232	            for(int col = 0; col < field.getWidth(); col++) 
233	            {
234	                Animal animal = (Animal) field.getObjectAt(row, col, Animal.class);
235	                Plant plant = (Plant) field.getObjectAt(row, col, Plant.class);
236	                
237	                if(animal != null) 
238	                {
239	                    stats.incrementCount(animal.getClass());
240	                    fieldView.drawMark(col, row, getColor(animal.getClass()));
241	                    
242	                    // Update the infected and immune counts
243	                    if (animal.getIsInfected())
244	                    {
245	                        numberOfInfected++;
246	                    }
247	                    
248	                    if (animal.getIsImmune())
249	                    {
250	                        numberOfImmune++;
251	                    }
252	                }
253	                // Only show the plant if an animal is not present
254	                else if(plant != null) 
255	                {
256	                    fieldView.drawMark(col, row, getColor(plant.getClass()));
257	                }
258	                else 
259	                {
260	                    Color emptyColor = EMPTY_COLOR;
261	                    fieldView.drawMark(col, row, emptyColor);
262	                    fieldView.setBackground(emptyColor);
263	                }
264	                
265	                if (plant != null) 
266	                {
267	                   stats.incrementCount(plant.getClass()); 
268	                }
269	            }
270	        }
271	        
272	        stats.countFinished();
273	        
274	        infectedLabel.setText(INFECTED_PREFIX + numberOfInfected);
275	        immuneLabel.setText(IMMUNE_PREFIX + numberOfImmune);
276	
277	        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
278	        fieldView.repaint();
279	    }
280	
281	    /**
282	     * Determine whether the simulation should continue to run.
283	     * 
284	     * @param field The field to check viability.
285	     *
286	     * @return True if there is more than one species alive.
287	     */
288	    public boolean isViable(Field field)
289	    {
290	        return stats.isViable(field);
291	    }
292	    
293	    /**
294	     * @return Returns the properly formated time in 24 hr format.
295	     */
296	    private String getTimeString()
297	    {
298	        int time = Time.getTime();
299	        if (time >= 12){
300	            return time + ":00 ";
301	        }
302	        else {
303	            if(time<10){
304	                return "0" + time + ":00 ";
305	            }
306	            else {
307	                return time + ":00 ";
308	            }
309	        }
310	    }
311	    
312	    /**
313	     * Provide a graphical view of a rectangular field. This is 
314	     * a nested class (a class defined inside a class) which
315	     * defines a custom component for the user interface. This
316	     * component displays the field.
317	     */
318	    private class FieldView extends JPanel
319	    {
320	        private final int GRID_VIEW_SCALING_FACTOR = 6;
321	
322	        private int gridWidth, gridHeight;
323	        private double xScale, yScale;
324	        Dimension size;
325	        private Graphics g;
326	        private Image fieldImage;
327	
328	        /**
329	         * Create a new FieldView component.
330	         */
331	        public FieldView(int height, int width)
332	        {
333	            gridHeight = height;
334	            gridWidth = width;
335	            size = new Dimension(0, 0);
336	        }
337	
338	        /**
339	         * Tell the GUI manager how big we would like to be.
340	         * 
341	         * @return Dimensions
342	         */
343	        public Dimension getPreferredSize()
344	        {
345	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
346	                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
347	        }
348	
349	        /**
350	         * Prepare for a new round of painting. Since the component
351	         * may be resized, compute the scaling factor again.
352	         */
353	        public void preparePaint()
354	        {
355	            if(! size.equals(getSize())) {  // if the size has changed...
356	                size = getSize();
357	                fieldImage = fieldView.createImage(size.width, size.height);
358	                g = fieldImage.getGraphics();
359	            
360	                xScale = size.width / gridWidth;
361	                if(xScale < 1) {
362	                    xScale = GRID_VIEW_SCALING_FACTOR;
363	                }
364	                yScale = size.height / gridHeight;
365	                if(yScale < 1) {
366	                    yScale = GRID_VIEW_SCALING_FACTOR;
367	                }
368	                
369	                // Makes sure that the grid remains in proportion
370	                // (the grid squares remain as squares)
371	                if(xScale > yScale) {
372	                    xScale = yScale;
373	                }
374	                else if(xScale < yScale) {
375	                    yScale = xScale;
376	                }
377	            }
378	        }
379	        
380	        /**
381	         * Paint on grid location on this field in a given color.
382	
383	         * @param x X-position to draw the mark
384	         * @param y Y-position to draw the mark
385	         * @param color The colour to draw the mark
386	         */
387	        private void drawMark(int x, int y, Color color)
388	        {
389	            g.setColor(color);
390	            g.fillRect((int)(x * xScale), (int)(y * yScale) , (int)(xScale - 1.0), (int)(yScale - 1.0));
391	        }
392	
393	        /**
394	         * The field view component needs to be redisplayed. Copy the
395	         * internal image to screen.
396	         * 
397	         * @param g Graphics
398	         */
399	        public void paintComponent(Graphics g)
400	        {
401	            if(fieldImage != null) 
402	            {
403	                Dimension currentSize = getSize();
404	                
405	                if(size.equals(currentSize)) 
406	                {
407	                    g.drawImage(fieldImage, 0, 0, null);
408	                }
409	                else 
410	                {
411	                    // Rescale the previous image.
412	                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
413	                }
414	            }
415	        }
416	    }
417	}
