4	/**
5	 * Plants can grow, be can be partially eaten, they can be completely eaten and die, plants
6	 * can spread (the weather effects their ability to spread).
7	 *
8	 * @version 26/02/2022
9	 */
10	public class Plant extends LivingOrganism
11	{
12	    // its current health percentage
13	    private double healthPercentage;
14	    // The likelihood a plants being able to spread into areas with no plants
15	    private double spreadProbability;
16	    // The rate at which plants grow back and increase their health percentage
17	    private static final double GROWTH_RATE = 0.05;
18	    // The amount of health percentage which is taken away every time an animal eats a plant
19	    private static final double PERCENTAGE_EATEN = 0.52;
20	    // The food value of itself - how much the hunter's food level increases when eating it.
21	    private static final int FOOD_VALUE = 3;
22	    
23	    /**
24	     * Create a new PLANT at location in field.
25	     * 
26	     * @param randomHealthPercentage If true, the plant will have a random age.
27	     * @param field The field currently occupied.
28	     * @param location The location within the field.
29	     */
30	    public Plant(boolean randomHealthPercentage, Field field, Location location) 
31	    {
32	        super(field, location);
33	        
34	        foodValue = FOOD_VALUE;
35	        
36	        healthPercentage = 1;
37	        if (randomHealthPercentage) 
38	        {
39	            healthPercentage = rand.nextDouble();
40	            
41	            if (healthPercentage < 0.1)
42	            {
43	                healthPercentage = 0.1;
44	            }
45	        }
46	    }
47	    
48	    /**
49	     * @Override
50	     * 
51	     * This is what the plants does most of the time - it runs 
52	     * around. Sometimes it will breed or die of old age.
53	     * 
54	     * @param newPlants A list to return new Plants.
55	     */
56	    public void act(List<LivingOrganism> newPlants)
57	    {
58	        incrementAge();
59	        if(!Time.isNight()) 
60	        {
61	            if(isAlive()) 
62	            {
63	                switch (Weather.getWeather())
64	                {
65	                    case Sunny:
66	                        spreadProbability = 0.2;
67	                        break;
68	                    case Rainy:
69	                        spreadProbability = 0.14;
70	                        break;
71	                    case Foggy:
72	                        spreadProbability = 0.05;
73	                        break;
74	                    case Cloudy:
75	                        spreadProbability = 0.1;
76	                        break;
77	                    case Clear:
78	                        spreadProbability = 0.08;
79	                        break;
80	                }    
81	                
82	                if (rand.nextDouble() < spreadProbability) 
83	                {
84	                    populate(newPlants);
85	                }
86	            }
87	        }
88	    }
89	    
90	    /**
91	     * When called, the plant gets eaten and loses a
92	     * pre-defined amount of health.
93	     */
94	    protected int beEaten() 
95	    {
96	        healthPercentage -= PERCENTAGE_EATEN;
97	        if (healthPercentage <= 0)
98	        {
99	            setDead();
100	        }
101	        
102	        return foodValue;
103	    }
104	    
105	    /**
106	     * @Override
107	     *
108	     * Makes the plant grow to full health.
109	     */
110	    protected void incrementAge() 
111	    {
112	        healthPercentage += GROWTH_RATE;
113	        if (healthPercentage > 1.0) 
114	        {
115	            healthPercentage = 1.0;
116	        }
117	    }
118	
119	    /**
120	     * @Override
121	     * 
122	     * Indicate that the animal is no longer alive.
123	     * It is removed from the field.
124	     */
125	    protected void setDead()
126	    {
127	        alive = false;
128	        if(location != null) 
129	        {
130	            field.clear(location, Plant.class);
131	            location = null;
132	        }
133	    }
134	    
135	    /**
136	     * @Override
137	     * 
138	     * Place the plant at the new location in the given field.
139	     * 
140	     * @param newLocation The plant's new location.
141	     */
142	    protected void setLocation(Location newLocation)
143	    {
144	        if(location != null) 
145	        {
146	            field.clear(location, Plant.class);
147	        }
148	        
149	        location = newLocation;
150	        field.place(this, newLocation);
151	    }
152	    
153	    /**
154	     * @Override
155	     * 
156	     * Check whether or not this Plant is to give birth at this step.
157	     * New births will be made into free adjacent locations.
158	     * 
159	     * @param newPlants A list to return newly born Plants.
160	     */
161	    protected void populate(List<LivingOrganism> newPlants)
162	    {
163	        // Get a list of adjacent free locations.
164	        Field field = getField();
165	        List<Location> free = field.getFreeAdjacentLocations(getLocation(), Plant.class);
166	        
167	        // New plants are spread into adjacent locations.
168	        for(int b = 0; free.size() > 0; b++) 
169	        {
170	            newPlants.add(createOffspring(free));
171	        }
172	    }
173	    
174	    /**
175	     * Used to instantiate baby plantlets
176	     * 
177	     * @param free List of free locations to spawn
178	     * @return Returns a new plant object.
179	     */
180	    private Plant createOffspring(List<Location> free) 
181	    {
182	        Location loc = free.remove(0);
183	        Plant offspring = null;
184	        
185	        offspring = new Plant(false, field, loc);
186	        
187	        return offspring;
188	    }
189	}
