67	     */
68	    protected Location findFood()
69	    {
70	        Field field = getField();
71	        List<Location> adjacent = field.adjacentLocations(getLocation());
72	        Iterator<Location> it = adjacent.iterator();
73	        
74	        while(it.hasNext()) 
75	        {
76	            Location where = it.next();
77	            Object animal = field.getObjectAt(where, Animal.class);
78	            
79	            if(animal instanceof Prey) 
80	            {
81	                Prey prey = (Prey) animal;
82	                if(prey.isAlive() && foodLevel < maxFoodLevel && rand.nextDouble() < preyCatchingProbability) 
83	                { 
84	                    // Predator is hungry and prey is availiable so eat
85	                    // the prey.
86	                    int preyFoodValue = prey.beEaten();
87	                    foodLevel += preyFoodValue;
88	                    
89	                    // if the prey being eaten is infected then the predator most likely
90	                    // gets infected
91	                    if (prey.getIsInfected() && !getIsImmune() && rand.nextDouble() <= diseaseSpreadProbability)
92	                    {
93	                        this.infected = true; 
94	                    }
95	                    
96	                    return where;
97	                }
98	            }
99	        }
100	        
101	        return null;
102	    }
