1	/**
2	 * A class which is used to access the step number, time, and
3	 * whether the simulation has finished or paused.
4	 *
5	 * @version 26/02/2022
6	 */
7	public class Time
8	{
9	    private static int step = 0;
10	    
11	    // The offset of the time to start the simulation at.
12	    private static final int TIME_OFFSET = 12;
13	    
14	    // Stores the actual number of steps that the current
15	    // run of the simulation should pause at if viable.
16	    private static int stepsToRunUntil;
17	    
18	    // Stores the starting point of the current run of the
19	    // simulation.
20	    private static int stepOffset;
21	    
22	    // Stores whether the simulation is paused or not
23	    private static boolean isPaused = true;
24	    
25	    /**
26	     * Increments the step number.
27	     */
28	    public static void incrementStep() 
29	    {
30	        step++;
31	    }
32	    
33	    /**
34	     * @return Returns the current step number.
35	     */
36	    public static int getStep() 
37	    {
38	        return step;
39	    }
40	    
41	    /**
42	     * Resets the step number and pauses the simulation.
43	     */
44	    public static void resetStep() 
45	    {
46	        step = 0;
47	        stepsToRunUntil = 0;
48	        stepOffset = 0;
49	        isPaused = true;
50	    }
51	    
52	    /**
53	     * @return Returns the time in hours (between 0 and 24).
54	     */
55	    public static int getTime() {
56	        int time = (step + TIME_OFFSET)%24;
57	        return time;
58	    }
59	    
60	    /**
61	     * @return Returns if it is currently night.
62	     */
63	    public static boolean isNight() {
64	        boolean isNight = false;
65	        int time = getTime();
66	        if (time < 6 || time > 18) {
67	            isNight = true;
68	        }
69	        return isNight;
70	    }
71	    
72	    /**
73	     * Sets the number of steps to run the simulation for.
74	     * @param The number of steps to run the simulation for.
75	     */
76	    public static void setStepsToRunFor(int stepsToRunFor) {
77	        stepOffset = step;
78	        stepsToRunUntil = stepsToRunFor + Time.getStep();
79	    }
80	    
81	    /**
82	     * @return Returns the step number to pause the current run
83	     * of the simualtion at.
84	     */
85	    public static int getStepsToRunUntil() {
86	        return stepsToRunUntil;
87	    }
88	    
89	    /**
90	     * Set whether the simulation is paused or not.
