3	/**
4	 * A class which is used to access the weather and handle changing
5	 * weather.
6	 *
7	 * @version 26/02/2022
8	 */
9	public class Weather {
10	    // Stores all of the possible weather types.
11	    public static enum WeatherType { Sunny, Rainy, Foggy, Clear, Cloudy }
12	    
13	    private static WeatherType currentWeather;
14	    
15	    private static int weatherLastsForSteps;
16	    private static final int MINIMUM_STEPS_WEATHER_LASTS_FOR = 27;
17	    
18	    // Stores a randomiser used for generating random weather.
19	    private static final Random rand = Randomizer.getRandom();
20	    
21	    /**
22	     * @return Returns the current weather.
23	     */
24	    public static WeatherType getWeather() 
25	    {
26	        if (currentWeather == null) 
27	        {
28	            currentWeather = pickRandomWeather();
29	        }
30	        
31	        return currentWeather;
32	    }
33	    
34	    /**
35	     * Updates the weather and picks a random weather after a
36	     * random amount of steps.
37	     */
38	    public static void updateWeather() 
39	    {
40	        if (weatherLastsForSteps == 0) 
41	        {
42	            currentWeather = pickRandomWeather();
43	        }
44	        else 
45	        {
46	            weatherLastsForSteps--;
47	        }
48	        
49	        // Sunny can only occur during daytime; clear can only occur at 
50	        // night.
51	        if (Time.isNight() && currentWeather.equals(WeatherType.Sunny)) 
52	        {
53	            currentWeather = currentWeather.Clear;
54	        }
55	        
56	        if (!Time.isNight() && currentWeather.equals(WeatherType.Clear)) 
57	        {
58	            currentWeather = currentWeather.Sunny;
59	        }
60	    }
61	    
62	    /**
63	     * @return Returns a random weather type.
64	     */
65	    private static WeatherType pickRandomWeather() 
66	    {
67	        int randomInt = rand.nextInt(WeatherType.values().length);
68	        
69	        weatherLastsForSteps = rand.nextInt(20) + MINIMUM_STEPS_WEATHER_LASTS_FOR;
70	        
71	        return WeatherType.values()[randomInt];
72	    }
73	}

