3	/**
4	 * Provide control over the randomization of the simulation. By using the shared, fixed-seed 
5	 * randomizer, repeated runs will perform exactly the same (which helps with testing). Set 
6	 * 'useShared' to false to get different random behaviour every time.
7	 *
8	 * @version 2016.02.29
9	 */
10	public class Randomizer
11	{
12	    // The default seed for control of randomization.
13	    private static final int SEED = 1111;
14	    // A shared Random object, if required.
15	    private static final Random rand = new Random(SEED);
16	    // Determine whether a shared random generator is to be provided.
17	    private static final boolean useShared = false;
18	
19	    /**
20	     * Provide a random generator.
21	     * @return A random object.
22	     */
23	    public static Random getRandom()
24	    {
25	        if(useShared) {
26	            return rand;
27	        }
28	        else {
29	            return new Random();
30	        }
31	    }
32	    
33	    /**
34	     * Reset the randomization.
35	     * This will have no effect if randomization is not through
36	     * a shared Random generator.
37	     */
38	    public static void reset()
39	    {
40	        if(useShared) {
41	            rand.setSeed(SEED);
42	        }
43	    }
44	}
