2	import java.util.HashMap;
3	
4	/**
5	 * This class collects and provides some statistical data on the state 
6	 * of a field. It is flexible: it will create and maintain a counter 
7	 * for any class of object that is found within the field.
8	 *
9	 * @version 26/02/2022
10	 */
11	public class FieldStats
12	{
13	    // Counters for each type of entity (lion, zebra, etc.) in the simulation.
14	    private HashMap<Class, Counter> counters;
15	    // Whether the counters are currently up to date.
16	    private boolean countsValid;
17	
18	    /**
19	     * Construct a FieldStats object.
20	     */
21	    public FieldStats()
22	    {
23	        // Set up a collection for counters for each type of animal that
24	        // we might find
25	        counters = new HashMap<>();
26	        countsValid = true;
27	    }
28	
29	    /**
30	     * Get details of what is in the field.
31	     * 
32	     * @param field The field to get the population details of.
33	     * 
34	     * @return A string describing what is in the field.
35	     */
36	    public String getPopulationDetails(Field field)
37	    {
38	        StringBuffer buffer = new StringBuffer();
39	        if(!countsValid) {
40	            generateCounts(field);
41	        }
42	        for(Class key : counters.keySet()) {
43	            Counter info = counters.get(key);
44	            buffer.append(info.getName());
45	            buffer.append(": ");
46	            buffer.append(info.getCount());
47	            buffer.append(' ');
48	        }
49	        return buffer.toString();
50	    }
51	    
52	    /**
53	     * Invalidate the current set of statistics; reset all 
54	     * counts to zero.
55	     */
56	    public void reset()
57	    {
58	        countsValid = false;
59	        for(Class key : counters.keySet()) {
60	            Counter count = counters.get(key);
61	            count.reset();
62	        }
63	    }
64	
65	    /**
66	     * Increment the count for one object.
67	     * 
68	     * @param objectType The class of animal to increment.
69	     */
70	    public void incrementCount(Class objectType)
71	    {
72	        Counter count = counters.get(objectType);
73	        if(count == null) {
74	            // We do not have a counter for this species yet.
75	            // Create one.
76	            count = new Counter(objectType.getName());
77	            counters.put(objectType, count);
78	        }
79	        count.increment();
80	    }
81	
82	    /**
83	     * Indicate that an animal count has been completed.
84	     */
85	    public void countFinished()
86	    {
87	        countsValid = true;
88	    }
89	
90	    /**
91	     * Determine whether the simulation is still viable.
92	     * I.e., should it continue to run.
93	     * 
94	     * @return true If there is more than one species alive.
95	     */
96	    public boolean isViable(Field field)
97	    {
98	        // How many counts are non-zero.
99	        int nonZero = 0;
100	        if(!countsValid) 
101	        {
102	            generateCounts(field);
103	        }
104	        
105	        for(Class key : counters.keySet()) 
106	        {
107	            Counter info = counters.get(key);
108	            if(info.getCount() > 0) 
109	            {
110	                nonZero++;
111	            }
112	        }
113	        return nonZero > 1;
114	    }
115	    
116	    /**
117	     * Generate counts of the number of all species of 
118	     * animal and plant.
119	     * These are not kept up to date as animals and plants
120	     * are placed in the field, but only when a request
121	     * is made for the information.
122	     * 
123	     * @param field The field to generate the stats for.
124	     */
125	    private void generateCounts(Field field)
126	    {
127	        reset();
128	        for(int row = 0; row < field.getDepth(); row++) 
129	        {
130	            for(int col = 0; col < field.getWidth(); col++) 
131	            {
132	                Object object = field.getObjectAt(row, col, Animal.class);
133	                
134	                if(object != null) 
135	                {
136	                    incrementCount(object.getClass());
137	                }
138	            }
139	        }
140	        
141	        countsValid = true;
142	    }
143	}
