1	import java.util.List;
2	import java.util.Iterator;
3	/**
4	 * A class representing shared characteristics of animals.
5	 *
6	 * @version 25/02/2022
7	 */
8	public abstract class Animal extends LivingOrganism
9	{
10	    // Indicates whether an animal is a female or not;
11	    protected boolean isFemale;    
12	    // The age at which an animal can start to breed.
13	    protected int breedingAge;
14	    // The age to which an animal can live.
15	    protected int maxAge;
16	    // The likelihood of an animal breeding.
17	    protected double breedingProbability;
18	    // whther the animal is infected or not
19	    protected boolean infected;
20	    // The likelihood of an animal having a disease.
21	    protected double diseaseProbability;
22	    // The likelihood of an animal catching a disease from another animal
23	    protected double diseaseSpreadProbability;
24	    // The likelihood of an animal dying from catching the disease
25	    protected double deathFromInfectionProbability;
26	    // The likelihood of an animal becomming immune to the disease
27	    protected double immuneProbability;
28	    // whether the animal is immune or not
29	    protected boolean immune;
30	    // The maximum number of births.
31	    protected int maxLitterSize;
32	    // The animals's age.
33	    protected int age;
34	    // The animals's food level, which is increased by eating prey.
35	    protected int foodLevel;
36	    // The maximum food level that an animal will eat at. The food level they will stop
37	    // being hungry at
38	    protected int maxFoodLevel;
39	    // Probability that an animal will move at a given step.
40	    protected double movementProbability;
41	    
42	    /**
43	     * Create a new animal at location in field.
44	     * 
45	     * @param field The field currently occupied.
46	     * @param location The location within the field.
47	     * @param infected Intial state if the animal is infected or not
48	     * @param immmune Intial state if the animal is immune or not
49	     */
50	    public Animal(Field field, Location location, boolean infected, boolean immune)
51	    {
52	        super(field, location);
53	        alive = true;
54	        this.infected = infected;
55	        this.immune = immune;
56	        
57	        diseaseProbability = 0.00000015;
58	        diseaseSpreadProbability = 0.80;
59	        deathFromInfectionProbability = 0.13;
60	        immuneProbability = 0.05;
61	        
62	        isFemale = rand.nextBoolean();
63	    }
64	    
65	    /**
66	     * @Override
67	     * 
68	     * Make this animal act - that is: make it do
69	     * whatever it wants/needs to do.
70	     * 
71	     * @param newAnimals A list to receive newly born animals.
72	     */
73	    public void act(List<LivingOrganism> newAnimals)
74	    {
75	        incrementAge();
76	        incrementHunger();
77	        
78	        // checks to see if the animal is going to die from it infection 
79	        // or become immune
80	        // if the animal becomes immune then it no longer is infected
81	        if (!getIsImmune() && getIsInfected()) 
82	        {
83	            if(rand.nextDouble() <= deathFromInfectionProbability) 
84	            {
85	                setDead();            
86	            }
87	            else if(rand.nextDouble() <= immuneProbability) {
88	                immune = true;
89	                infected = false;
90	            }
91	        }
92	        // If the animal is immune and not infected, there is a chance
93	        // of losing immunity.
94	        else
95	        {
96	            if(rand.nextDouble() <= (immuneProbability / 15)) {
97	                immune = false;
98	            }
99	        }
100	        
101	        if(isAlive()) 
102	        {
103	            if(!getIsImmune() && !getIsInfected())
104	            {
105	                // checks to see if the animal is going to catch a disease from
106	                // its surroundings.
107	
108	                if (surroundingsInfected() && rand.nextDouble() <= diseaseSpreadProbability)
109	                {
110	                    infected = true;
111	                }
112	                
113	                // checks to see if the animal is going to get a disease out 
114	                // of nowhere.
115	                else if (rand.nextDouble() <= diseaseProbability) 
116	                {
117	                    infected = true;           
118	                }
119	            }
120	            
121	            // checks to see if the animal is able to give birth
122	            if(this.getIsFemale()) 
123	            {
124	                if(canBreed() && rand.nextDouble() <= breedingProbability)
125	                {
126	                    populate(newAnimals);
127	                }
128	            }
129	
130	            // Move towards a source of food if found.
131	            Location newLocation = findFood();
132	            
133	            if(newLocation == null) 
134	            { 
135	                Location possibleNewLocation = getField().freeAdjacentLocation(getLocation(), Animal.class);
136	                
137	                if (possibleNewLocation == null) 
138	                {
139	                    // no free adjacent locations therefore it is 
140	                    // overcrowded
141	                    if (rand.nextDouble() < 0.3) 
142	                    {
143	                        setDead();
144	                    }
145	                }
146	                
147	                // No food found and there is a free location - move there.
148	                if (rand.nextDouble() <= movementProbability) 
149	                {
150	                    newLocation = possibleNewLocation;
151	                }
152	            }
153	            
154	            // Move to new location
155	            if(newLocation != null)
156	            { 
157	                setLocation(newLocation);
158	            }
159	        }
160	    }
161	    
162	    /**
163	     * Look for food adjacent to the current location.
164	     * Only the first live prey or plant is eaten.
165	     * 
166	     * @return Where food was found, or null if it wasn't.
167	     */
168	    abstract protected Location findFood();
169	
170	    /**
171	     * @Override
172	     * 
173	     * Indicate that the animal is no longer alive.
174	     * It is removed from the field.
175	     */
176	    protected void setDead()
177	    {
178	        alive = false;
179	        
180	        if(location != null) 
181	        {
182	            field.clear(location, Animal.class);
183	            location = null;
184	        }
185	        
186	        if (this.getClass().equals(Lion.class) || this.getClass().equals(Cheetah.class)){
187	            location = null;
188	        }
189	    }
190	    
191	    /**
192	     * @Override
193	     * 
194	     * When called, the animal is killed and returns
195	     * its food value.
196	     * 
197	     * @return The food value of the animal eaten.
198	     */
199	    protected int beEaten() 
200	    {
201	        setDead();
202	        
203	        return foodValue;
204	    }
205	    
206	    /**
207	     * @Override
208	     * 
209	     * Place the animal at the new location in the given field.
210	     * 
211	     * @param newLocation The animal's new location.
212	     */
213	    protected void setLocation(Location newLocation)
214	    {
215	        if(location != null) 
216	        {
217	            if(field.getObjectAt(location, Animal.class) != null)
218	            {
219	                field.clear(location, Animal.class);
220	            }
221	        }
222	        
223	        location = newLocation;
224	        field.place(this, newLocation);
225	    }
226	    
227	    /**
228	     * Returns the gender of the animal.
229	     * 
230	     * @return Returns true if female.
231	     */
232	    protected boolean getIsFemale() 
233	    {
234	        return isFemale;
235	    }
236	    
237	    /**
238	     * @Override
239	     * 
240	     * Increase the age.
241	     * This could result in the Animal's death.
242	     */
243	    protected void incrementAge()
244	    {
245	        age++;
246	        if(age > maxAge) {
247	            setDead();
248	        }
249	    }
250	    
251	    /**
252	     * Make this animal's more hungry. This could result in the animal's death.
253	     */
254	    protected void incrementHunger()
255	    {
256	        foodLevel--;
257	        if(foodLevel <= 0) {
258	            setDead();
259	        }
260	    }
261	    
262	    /**
263	     * @Override
264	     * 
265	     * New births will be made into free adjacent locations.
266	     * @param newAnimals A list to return newly born Animals.
267	     */
268	    protected void populate(List<LivingOrganism> newAnimals)
269	    {
270	        // Get a list of adjacent free locations.
271	        Field field = getField();
272	        List<Location> free = field.getFreeAdjacentLocations(getLocation(), Animal.class);
273	        //determines the number of offspring the animal will produce
274	        
275	        int births = breed();
276	        // New animals are born into adjacent locations.
277	        
278	        for(int b = 0; b < births && free.size() > 0; b++) 
279	        {
280	            Animal newAnimal = createNewOffspring(this.getClass(), free, infected, immune, foodLevel);
281	            newAnimals.add(newAnimal);
282	        }
283	    }
284	    
285	    /**
286	     * Creates a new offspring and places it into the field at the first free location
287	     * 
288	     * @param classOfAnimal The class type of the new animal
289	     * @param free A list of the free adjacent location
290	     * @param motherIsInfected If the mother has currently the disease, so will the child
291	     * 
292	     * @return Returns the new animal
293	     */
294	    protected Animal createNewOffspring(Class classOfAnimal, List<Location> free, boolean motherIsInfected, boolean motherIsImmune, int motherFoodLevel)
