2	import java.util.Iterator;
3	/**
4	 * A class representing the shared characteristics between predators
5	 *
6	 * @version 25/02/2022
7	 */
8	public abstract class Predator extends Animal
9	{
10	    // The likelihood of the predator catching its prey
11	    protected double preyCatchingProbability;
12	
13	    /**
14	     * Create a new predator at location in field.
15	     * 
16	     * @param field The field currently occupied.
17	     * @param location The location within the field.
18	     * @param infected : intial state if the prey is infected or not
19	     * @param immmune : intial state if the prey is immune or not
20	     */
21	    protected Predator(Field field, Location location, boolean isInfected, boolean isImmune)
22	    {
23	        super(field, location, isInfected, isImmune);
24	        movementProbability = 0.8;
25	    }
26	    
27	    /**
28	     * @Override
29	     * 
30	     * This is what the predators does most of the time - it may move around, it eats prey, 
31	     * it may breed, it may get infected with a disease, it may become immune to that disease, 
32	     * it may die of the disease, it may die of hunger, and it may die of old age.
33	     * 
34	     * @param newPredators A list to return newly born prey.
35	     */
36	    public void act(List<LivingOrganism> newPredators)
37	    {
38	        // Predators have a lower chance of acting when its night
39	        if(Time.isNight()) 
40	        {
41	            if (rand.nextDouble() > 0.25)
42	            {
43	                return;
44	            }
45	        }
46	        
47	        // Predators have a lower chance of acting when its foggy
48	        if (Weather.getWeather() == Weather.WeatherType.Foggy) 
49	        {
50	            if (rand.nextDouble() > 0.50)
51	            {
52	                return;
53	            }
54	        }
55	
56	        super.act(newPredators);
57	    }
58	    
59	    /**
60	     * @Override
61	     * 
62	     * Look for prey adjacent to the current location.
63	     * Eats prey till full.
64	     * Predators may catch the prey's disease if eaten.
65	     * 
66	     * @return Where food was found, or null if it wasn't.
67	     */
68	    protected Location findFood()
69	    {
70	        Field field = getField();
71	        List<Location> adjacent = field.adjacentLocations(getLocation());
72	        Iterator<Location> it = adjacent.iterator();
73	        
74	        while(it.hasNext()) 
75	        {
76	            Location where = it.next();
77	            Object animal = field.getObjectAt(where, Animal.class);
78	            
79	            if(animal instanceof Prey) 
